#!/usr/bin/env bash
# Bundle item 164 pa_nov25_notices (thread "Site: run the meeting archive", 23 Nov 2569 Bangkok, first run after the 4-day pause)
# Routine content update (AUTO UPDATES, Sukit 11 Nov 2569), Public Administration 2569 archive. Three meetings on Wed 25 Nov 2569,
# each from its published Senate notice letter (Rpublic 1), agenda only (not resolutions):
#   - main committee meeting 38/2569: notice ว 1057 (19 Nov 2569), 13.00, room CA 426 floor 4, the usual 5-part agenda
#     (approve minutes of 37/2569, subcommittee work, matters and petitions referred, matters within the committee's duties, next meeting)
#   - central and regional subcommittee meeting 32/2569: notice ว 1061 (19 Nov 2569), 09.00, room CB 315 floor 3, draft outline of the
#     study report on specific town plans under the Town Planning Act 2562 (urban conservation case study); Department of Public Works
#     and Town & Country Planning invited
#   - state administration development subcommittee meeting 17/2569: notice ว 1058 (19 Nov 2569), 09.30, room 405 floor 4, approve minutes
#     of 16/2569 and consider the summary of the 20 Nov seminar on the new facilitation act (name quoted as the notice writes it)
# Changes (committee-archive-2569 only; the home page cards follow through run_bundle.sh hub_snap_sync.py):
#   index.html  DATA (+38), TL (+38 planned entry), EZ calendar (37 -> 38), SHARE_V (+38), SUBS (+central 32, +dev 17, fetched), UPDATED
#   meetings.json (+38); sub-central.html / sub-dev.html DATA, TL (planned entry 31 -> 32 / 16 -> 17), EZ calendar, SHARE_V, UPDATED;
#   sub-central.json, sub-dev.json; 12 new files (3 share pages, 3 cards, 3 QR codes, 3 calendar files); 7 English lines (add-only).
#   A meeting's "media" is kept if a pre-meeting video item added it first.
# SELF-CONTAINED (shared folder over its cap, 22 Nov 2569): the payload is embedded at the end of this file; no payload folder.
# Surgical JSON-level edits of the live lines/files (a full build drifts from live). Idempotent; no git, no network. Needs $A69.
set -euo pipefail
T=164_pa_nov25_notices

main() {
  : "${A69:?A69 not set}"
  for f in index.html meetings.json i18n-en.json sub-central.html sub-central.json sub-dev.html sub-dev.json; do
    test -f "$A69/$f" || { echo "$T: A69/$f missing" >&2; exit 1; }
  done
  local TMP; TMP=$(mktemp -d); trap 'rm -rf "$TMP"' EXIT
  payload > "$TMP/p.tgz"
  tar -xzmf "$TMP/p.tgz" -C "$TMP"
  test -f "$TMP/payload.json" -a -f "$TMP/en_add.json" || { echo "$T: embedded payload broken" >&2; exit 1; }

  # 1) new files (refuse to overwrite a different file of the same name)
  mkdir -p "$A69/s" "$A69/img/s" "$A69/cal" "$A69/cal-sub/central" "$A69/cal-sub/dev"
  for f in s/38.html img/s/38-7e5a59d5.jpg img/s/qr-38.svg cal/38.ics \
           s/central-32.html img/s/central-32-ee63a8e7.jpg img/s/qr-central-32.svg cal-sub/central/32.ics \
           s/dev-17.html img/s/dev-17-8cbaa921.jpg img/s/qr-dev-17.svg cal-sub/dev/17.ics; do
    if [ -f "$A69/$f" ] && ! cmp -s "$TMP/files/$f" "$A69/$f"; then echo "$T: $f already exists with other content; not overwriting" >&2; exit 1; fi
    cmp -s "$TMP/files/$f" "$A69/$f" 2>/dev/null || cp -f "$TMP/files/$f" "$A69/$f"; cmp -s "$TMP/files/$f" "$A69/$f"
  done

  # 2) data lines and files
  python3 - "$A69" "$TMP" <<'PY'
import json, os, sys
A69, D = sys.argv[1:3]
P = json.load(open(os.path.join(D, 'payload.json'), encoding='utf-8'))
dec = json.JSONDecoder()
SERS = [lambda v: json.dumps(v, ensure_ascii=False, separators=(',', ':')).replace('</', '<\\/'),
        lambda v: json.dumps(v, ensure_ascii=False),
        lambda v: json.dumps(v, ensure_ascii=False, separators=(',', ':')),
        lambda v: json.dumps(v, ensure_ascii=False).replace('</', '<\\/')]
changed = []

def put(path, text):
    if open(path, encoding='utf-8').read() != text:
        open(path, 'w', encoding='utf-8').write(text); changed.append(os.path.basename(path))

class Page:
    def __init__(self, path):
        self.path = path; self.lines = open(path, encoding='utf-8').read().split('\n')
    def edit(self, pfx, fn):
        idx = [k for k, l in enumerate(self.lines) if l.startswith(pfx)]
        assert len(idx) == 1, f'{os.path.basename(self.path)}: {pfx} not found once'
        l = self.lines[idx[0]]; v, e = dec.raw_decode(l[len(pfx):]); rest = l[len(pfx) + e:]
        ser = next((s for s in SERS if pfx + s(v) + rest == l), None)
        assert ser, f'{os.path.basename(self.path)}: {pfx} does not round-trip; not touching it'
        self.lines[idx[0]] = pfx + ser(fn(v)) + rest
    def save(self):
        put(self.path, '\n'.join(self.lines))

def keep_media(old, new):
    out = dict(new); out['media'] = old.get('media', {})
    return {k: out[k] for k in new.keys()}

def upd_meeting(arr, key, new, media=True):
    """replace meeting `key` (n, date) with `new` (keeping live media), or insert it newest-first when missing."""
    i = [k for k, m in enumerate(arr) if (m['n'], m['date']) == key]
    if i:
        assert len(i) == 1, f'{key} found twice'
        arr[i[0]] = keep_media(arr[i[0]], new) if media and 'media' in new else new
    else:
        assert not any(m['n'] == key[0] and m['date'][:4] == key[1][:4] for m in arr), f'a different meeting {key[0]} is already there'
        at = next((k for k, m in enumerate(arr) if (m['date'], m['n']) < (key[1], key[0])), len(arr))
        arr.insert(at, new)
    return arr

def is_auto_plan(x, n):
    return x[2] == 'cal' and x[5] == 'plan' and isinstance(x[6], int) and x[6] <= n and str(x[3]).startswith('นัดประชุมครั้งที่')

def tl_put(v, entry, drop):
    v = [x for x in v if not drop(x)]
    at = next((q for q, x in enumerate(v) if x[0] > entry[0]), len(v))
    v.insert(at, entry); return v

def ez_put(n, val):
    def f(v):
        cal = {k: c for k, c in (v.get('cal') or {}).items() if int(k) > n}
        v['cal'] = {str(n): val, **cal}; return v
    return f

def sv_put(n, val):
    def f(v):
        if str(n) in v:
            v[str(n)] = val; return v
        return {str(n): val, **v}
    return f

# --- main archive page
M = P['main']; KM = (M['n'], M['date'])
pg = Page(os.path.join(A69, 'index.html'))
pg.edit('const DATA=', lambda a: upd_meeting(a, KM, M['data']))
pg.edit('const TL=', lambda v: tl_put(v, M['tl'], lambda x: x[6] == M['n'] and x[5] == 'plan'))
pg.edit('const EZ=', ez_put(M['n'], M['ezcal']))
pg.edit('const SHARE_P="",SHARE_V=', sv_put(M['n'], M['share']))
def subs_main(v):
    for k in ('central', 'dev'):
        c = [s for s in v if s.get('key') == k]; assert len(c) == 1, f'SUBS: {k} not found once'
        upd_meeting(c[0]['meetings'], (P[k]['n'], P[k]['date']), P[k]['subs'], media=False)
    for s in v:
        s['fetched'] = max(s.get('fetched') or '', P['subs_fetched'])
    return v
pg.edit('const SUBS=', subs_main)
pg.edit('const UPDATED=', lambda v: max(v, P['updated']))
pg.save()

p = os.path.join(A69, 'meetings.json'); raw = open(p, encoding='utf-8').read(); ms = json.loads(raw)
assert json.dumps(ms, ensure_ascii=False, indent=1) == raw, 'meetings.json does not round-trip; not touching it'
put(p, json.dumps(upd_meeting(ms, KM, M['data']), ensure_ascii=False, indent=1))

# --- subcommittee pages
for k in ('central', 'dev'):
    S = P[k]; KS = (S['n'], S['date'])
    sp = Page(os.path.join(A69, f'sub-{k}.html'))
    sp.edit('const DATA=', lambda a: upd_meeting(a, KS, S['data']))
    sp.edit('const TL=', lambda v: tl_put(v, S['tl'], lambda x: is_auto_plan(x, S['n'])))
    sp.edit('const EZ=', ez_put(S['n'], S['ezcal']))
    sp.edit(f'const SHARE_P="{k}-",SHARE_V=', sv_put(S['n'], S['share']))
    sp.edit('const UPDATED=', lambda v: max(v, P['updated']))
    sp.save()
    p = os.path.join(A69, f'sub-{k}.json'); raw = open(p, encoding='utf-8').read(); sj = json.loads(raw)
    assert json.dumps(sj, ensure_ascii=False, indent=1) == raw, f'sub-{k}.json does not round-trip; not touching it'
    put(p, json.dumps(upd_meeting(sj, KS, S['json']), ensure_ascii=False, indent=1))

# --- English for the archive (add missing keys only, keep file format and order)
p = os.path.join(A69, 'i18n-en.json'); src = open(p, encoding='utf-8').read(); d = json.loads(src)
end = '\n}\n' if src.endswith('\n}\n') else '\n}'
ren = lambda x: '{\n' + ',\n'.join(json.dumps(a, ensure_ascii=False) + ': ' + json.dumps(b, ensure_ascii=False) for a, b in x.items()) + end
assert ren(d) == src, 'i18n-en.json does not round-trip; not touching it'
for a, b in json.load(open(os.path.join(D, 'en_add.json'), encoding='utf-8')).items():
    d.setdefault(a, b)
put(p, ren(d))
print('164_pa_nov25_notices: changed', len(changed), 'files:', ', '.join(changed) or 'none (already applied)')
PY

  # 3) final check
  python3 - "$A69" <<'PY' || { echo "$T: final check failed" >&2; exit 1; }
import json, os, sys
A = sys.argv[1]
def one(f, n):
    m = [x for x in json.load(open(os.path.join(A, f), encoding='utf-8')) if x['n'] == n and x['date'] == '2026-11-25']
    assert len(m) == 1, (f, n); return m[0]
m = one('meetings.json', 38); assert m['time'] == '13.00' and 'CA 426' in m['room'] and m.get('upcoming'), m
m = one('sub-central.json', 32); assert m['time'] == '09.00' and 'CB 315' in m['room'] and m.get('agenda_only'), m
m = one('sub-dev.json', 17); assert m['time'] == '09.30' and m['room'] == 'ห้องประชุม 405 ชั้น 4 อาคารรัฐสภา' and m.get('agenda_only'), m
PY
  echo "$T: done"
}

